interface IBase1
{
    void BaseGoo();
}
interface IBase2
{
    void BaseGoo();
}
interface IInterface : IBase1, IBase2
{
    void InterfaceGoo();
}
class C1 : IInterface
{
    public void BaseGoo() { System.Console.Write("BaseGoo ");}
    public void InterfaceGoo() { System.Console.Write("InterfaceGoo "); }
    public void Test()
    {
        C1 c = new C1();
        c.BaseGoo();
        c.InterfaceGoo();
        ((IBase1)c).BaseGoo();
        ((IBase2)c).BaseGoo();
        ((IInterface)c).InterfaceGoo();
        ((IInterface)c).BaseGoo();
    }
}

